/*
 * End-to-end round trip: loads reader pages generated by the Kotlin builder (ReaderPageFixtureTest,
 * READER_FIXTURE_DIR) in jsdom, enters edit mode without changing anything and checks the saved text
 * equals the original source byte for byte. Then edits one block and checks every other block survives.
 * Usage: node roundtrip.js <fixture-dir>
 */
const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');

const dir = process.argv[2];
if (!dir || !fs.existsSync(dir)) {
  console.error('fixture dir missing: ' + dir);
  process.exit(2);
}
let failures = 0, checked = 0;
function fail(name, msg, a, b) {
  failures++;
  console.log('FAIL ' + name + ': ' + msg);
  if (a !== undefined) { console.log('  expected: ' + JSON.stringify(a)); console.log('  actual  : ' + JSON.stringify(b)); }
}

for (const file of fs.readdirSync(dir).filter(f => f.endsWith('.html')).sort()) {
  const html = fs.readFileSync(path.join(dir, file), 'utf8');
  const errors = [];
  const dom = new JSDOM(html, {
    runScripts: 'dangerously',
    beforeParse(w) {
      w.scrollTo = () => {};
      w.scrollBy = () => {};
      w.FCBridge = new Proxy({}, { get: () => () => undefined });
      w.addEventListener('error', e => errors.push(String(e.message || e)));
    }
  });
  const w = dom.window;
  if (!w.FC || !w.FC._test) { fail(file, 'reader runtime did not load'); continue; }
  w.FC._test.init();
  const source = JSON.parse(w.document.getElementById('fc-source').textContent);
  const isMd = w.document.documentElement.classList.contains('kind-md');
  if (!w.FC.editor.enter(isMd ? 'rich' : 'source')) { fail(file, 'could not enter edit mode'); continue; }
  const out = w.FC.editor.serialize();
  checked++;
  if (out !== source) fail(file, 'unchanged document did not round-trip', source, out);
  if (errors.length) fail(file, 'script errors: ' + errors.join('; '));

  if (isMd) {
    // Edit the first top-level paragraph (if any) and make sure every other block is kept verbatim.
    const root = w.document.getElementById('document-content');
    const para = Array.from(root.children).find(el => el.nodeName === 'P' && el.hasAttribute('data-b'));
    if (para) {
      const b = parseInt(para.getAttribute('data-b'), 10);
      para.appendChild(w.document.createTextNode(' EDITED'));
      const edited = w.FC.editor.serialize();
      const blocks = Array.from(root.querySelectorAll('[data-b]')).map(el => ({
        b: parseInt(el.getAttribute('data-b'), 10), s: parseInt(el.getAttribute('data-s'), 10), e: parseInt(el.getAttribute('data-e'), 10)
      }));
      for (const blk of blocks) {
        if (blk.b === b) continue;
        const slice = source.slice(blk.s, blk.e);
        const want = source.indexOf('\r\n') >= 0 ? slice.replace(/\r?\n/g, '\r\n') : slice;
        if (!edited.includes(want)) fail(file, 'block ' + blk.b + ' changed after editing block ' + b, want, edited);
      }
      if (!edited.includes('EDITED')) fail(file, 'edit missing from output', 'EDITED', edited);
      // Undo-all style check: restoring the original DOM gives the original text again.
      para.lastChild.remove();
      if (w.FC.editor.serialize() !== source) fail(file, 'reverting the edit did not restore the source');
    }
  }
  w.FC.editor.exit();
}
console.log(`\nround trip: ${checked} documents, ${failures} failures`);
process.exit(failures || !checked ? 1 : 0);
